 </main>
 <footer class="bottom-footer"><span>SLICEBOUND <span style="color:#71889d">—</span> A LITTLE ARCADE MOMENT</span><span class="footer-right"><i class="live-dot"></i> READY TO PLAY</span></footer>
 </div>
 <script>
+(()=>{
+const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');
+const $=s=>document.querySelector(s), scoreEl=$('#score'),comboEl=$('#combo'),bestEl=$('#best'),timerEl=$('#timer'),overlay=$('#overlay'),pauseBtn=$('#pauseBtn'),startBtn=$('#startBtn'),toast=$('#comboToast');
+const TAU=Math.PI*2, fruits=[],particles=[],slashes=[],halves=[];
+let W=0,H=0,dpr=1,last=0,elapsed=0,spawnClock=0,score=0,combo=0,best=Number(localStorage.getItem('slicebound-best')||0),misses=0,state='ready',sound=true,audio=null,pointerDown=false,lastPointer=null,trail=[],toastTimer=0,shake=0;
+bestEl.textContent=String(best).padStart(4,'0');
+const types=[
+ {name:'citrus',color:'#ff9d42',light:'#ffd276',inner:'#ffe9a8',r:21},
+ {name:'apple',color:'#f75362',light:'#ff9b72',inner:'#ffd2a4',r:22},
+ {name:'kiwi',color:'#6cd69b',light:'#c5f58c',inner:'#edffb2',r:21},
+ {name:'plum',color:'#ad7cf7',light:'#e4a5ff',inner:'#ffe0ed',r:20},
+ {name:'lemon',color:'#f3d850',light:'#fff49a',inner:'#fff3bb',r:20}
+];
+function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}
+new ResizeObserver(resize).observe(canvas);resize();
+const rand=(a,b)=>a+Math.random()*(b-a),clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
+function soundFx(freq=440,duration=.08,wave='sine',volume=.035){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type=wave;o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(80,freq*.55),audio.currentTime+duration);g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}catch{}}
+function setScore(){scoreEl.textContent=String(score).padStart(4,'0');comboEl.textContent='×'+combo;bestEl.textContent=String(best).padStart(4,'0')}
+function startGame(){fruits.length=particles.length=slashes.length=halves.length=0;elapsed=0;spawnClock=.35;score=0;combo=0;misses=0;state='playing';last=performance.now();overlay.classList.add('hidden');pauseBtn.disabled=false;pauseBtn.setAttribute('aria-label','Pause game');timerEl.classList.remove('urgent');timerEl.innerHTML='<span>60</span> <small style="font-size:9px;color:#8398aa">SEC</small>';setScore();soundFx(520,.13,'triangle',.04);requestAnimationFrame(frame)}
+function pauseGame(){if(state==='playing'){state='paused';pauseBtn.setAttribute('aria-label','Resume game');showModal('Paused','Take a breath. Your fruit will wait right here.','Resume game','Ⅱ','Space to continue');}else if(state==='paused'){state='playing';overlay.classList.add('hidden');pauseBtn.setAttribute('aria-label','Pause game');last=performance.now();requestAnimationFrame(frame)}}
+function showModal(title,desc,button,icon,note){$('#modalTitle').textContent=title;$('#modalDesc').innerHTML=desc;startBtn.innerHTML=button+' <span aria-hidden="true">↗</span>';$('#modalIcon').textContent=icon;$('#modalNote').textContent=note;overlay.classList.remove('hidden')}
+function finishGame(){state='over';pointerDown=false;pauseBtn.disabled=true;const record=score>best;if(record){best=score;localStorage.setItem('slicebound-best',best);bestEl.textContent=String(best).padStart(4,'0')}showModal(record?'New personal best!':'Time well sliced.',`You scored <b>${score}</b> points with a best chain of <b>×${bestChain}</b>. ${record?'The orchard remembers.':'Ready for another round?'}`,'Play again',record?'🏆':'🍉','Drag to slice · Space to pause');soundFx(record?740:250,.35,'sine',.04)}
+let bestChain=0;
+function spawn(){const count=Math.random()<.25?3:Math.random()<.72?2:1,baseX=rand(W*.2,W*.8),bombChance=elapsed>8?.16:.09;for(let i=0;i<count;i++){const bomb=Math.random()<bombChance;const type=types[Math.floor(Math.random()*types.length)],r=bomb?20:type.r*rand(.88,1.12),x=clamp(baseX+(i-(count-1)/2)*rand(42,65),r+8,W-r-8);fruits.push({x,y:H+36,vx:rand(-115,115)+(x-W/2)*.08,vy:rand(-625,-510),r,type,bomb,rot:rand(-.4,.4),vr:rand(-2.2,2.2),age:0,id:Math.random(),cut:false})}}
+function burst(x,y,color,n=13){for(let i=0;i<n;i++){const a=rand(0,TAU),v=rand(50,260);particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v-rand(0,65),life:rand(.35,.8),max:.8,size:rand(2,5),color,rot:rand(0,TAU)})}}
+function cutFruit(f,x,y,chainDepth=0){if(f.cut)return;f.cut=true;combo++;bestChain=Math.max(bestChain,combo);const points=(f.bomb?0:10)*(1+Math.min(combo-1,9));score+=points;setScore();const col=f.bomb?'#ffc579':f.type.color;burst(x,y,col,f.bomb?28:17);slashes.push({x1:f.x,y1:f.y,x2:x,y2:y,life:.25,max:.25,color:chainDepth?'#d8ff72':'#a9fff1'});if(f.bomb){shake=10;soundFx(105,.22,'sawtooth',.055);combo=0;setScore();return}makeHalves(f);soundFx(460+Math.min(combo,8)*65,.1,'triangle',.025);if(combo>=2)showCombo(combo);if(chainDepth<4){const target=fruits.filter(o=>!o.cut&&!o.bomb&&o!==f&&Math.hypot(o.x-f.x,o.y-f.y)<155).sort((a,b)=>Math.hypot(a.x-f.x,a.y-f.y)-Math.hypot(b.x-f.x,b.y-f.y))[0];if(target){slashes.push({x1:f.x,y1:f.y,x2:target.x,y2:target.y,life:.3,max:.3,color:'#d8ff72'});setTimeout(()=>{if(state==='playing'&&!target.cut)cutFruit(target,target.x,target.y,chainDepth+1)},55)}}}
+function makeHalves(f){halves.push({x:f.x,y:f.y,vx:f.vx-.65*f.r,vy:f.vy*.15-25,rot:f.rot,vr:-2.3,r:f.r,type:f.type,side:-1,life:1.6},{x:f.x,y:f.y,vx:f.vx+.65*f.r,vy:f.vy*.15-25,rot:f.rot,vr:2.3,r:f.r,type:f.type,side:1,life:1.6})}
+function showCombo(n){$('#toastTitle').textContent=n>=5?'UNREAL!':n>=3?'JUICY!':'NICE!';$('#toastSub').textContent=n+'× CHAIN  ·  +'+(10*n);toast.classList.add('show');toastTimer=.75}
+function segmentHit(a,b,o){const dx=b.x-a.x,dy=b.y-a.y,len=dx*dx+dy*dy;if(!len)return Math.hypot(o.x-a.x,o.y-a.y)<o.r;const t=clamp(((o.x-a.x)*dx+(o.y-a.y)*dy)/len,0,1);return Math.hypot(o.x-(a.x+t*dx),o.y-(a.y+t*dy))<o.r+3}
+function pointerPos(e){const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}}
+canvas.addEventListener('pointerdown',e=>{e.preventDefault();canvas.setPointerCapture(e.pointerId);pointerDown=true;lastPointer=pointerPos(e);trail=[{...lastPointer,t:performance.now()}];combo=0;setScore()});
+canvas.addEventListener('pointermove',e=>{if(!pointerDown||state!=='playing')return;e.preventDefault();const p=pointerPos(e);trail.push({...p,t:performance.now()});if(trail.length>16)trail.shift();for(const f of fruits){if(!f.cut&&segmentHit(lastPointer,p,f))cutFruit(f,p.x,p.y)}lastPointer=p});
+function endPointer(){if(pointerDown&&combo===0){}pointerDown=false;lastPointer=null}canvas.addEventListener('pointerup',endPointer);canvas.addEventListener('pointercancel',endPointer);canvas.addEventListener('pointerleave',e=>{if(e.buttons===0)endPointer()});
+function drawBackground(){const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#102437');g.addColorStop(.58,'#11283a');g.addColorStop(1,'#0b1c2a');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);const glow=ctx.createRadialGradient(W*.5,H*.55,5,W*.5,H*.55,W*.65);glow.addColorStop(0,'rgba(73,132,142,.15)');glow.addColorStop(1,'rgba(5,15,24,0)');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H);
+ ctx.save();ctx.globalAlpha=.16;ctx.strokeStyle='#7fa6b6';ctx.lineWidth=1;for(let i=0;i<8;i++){const x=((i*173+elapsed*5)% (W+160))-80;ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x-25,H);ctx.stroke()}ctx.globalAlpha=.11;for(let i=0;i<5;i++){const y=H*.25+i*H*.15;ctx.beginPath();ctx.moveTo(0,y);ctx.quadraticCurveTo(W*.5,y-23,W,y+5);ctx.stroke()}ctx.restore();
+ // horizon and ambient firefly specks
+ const ground=ctx.createLinearGradient(0,H*.78,0,H);ground.addColorStop(0,'rgba(26,69,67,0)');ground.addColorStop(1,'rgba(26,69,67,.28)');ctx.fillStyle=ground;ctx.fillRect(0,H*.72,W,H*.28);for(let i=0;i<17;i++){const x=(i*89+37)%W,y=(i*127+49)%H;ctx.fillStyle=`rgba(181,240,217,${.16+.1*Math.sin(elapsed*1.6+i)})`;ctx.fillRect(x,y,2,2)}}

